'use strict';
const assert=require('node:assert/strict');
const {create}=require('../demo-core');
const F=require('../fixtures');
let tests=0;const test=(name,fn)=>{fn();tests++;console.log('PASS '+name);};
const authorized=c=>{c.requestPhone();c.resolvePhone('success');};
const ready=(scene='normal',clock)=>{const c=create({now:clock});c.setScenario(scene);authorized(c);c.select(['SIM_BJ01_U03']);c.setDate(F.defaultStart);return c;};
test('fixture identity and foreign keys',()=>{const stores=new Set(F.stores.map(s=>s.id)),ids=new Set(F.units.map(u=>u.id));assert.equal(stores.size,F.stores.length);assert.equal(ids.size,F.units.length);assert(F.units.every(u=>stores.has(u.store_id)&&u.base_month>0&&u.volume>0&&u.id.startsWith('SIM_')));assert(F.stores.every(s=>s.id.startsWith('SIM_')));});
test('home cubic prices derive from same units',()=>{for(const s of F.stores.filter(s=>s.status==='open')){const candidates=F.units.filter(u=>u.store_id===s.id&&u.status==='available');const expected=candidates.length?Number(Math.min(...candidates.map(u=>Math.round(u.base_month*12*.65/10)*10/12/u.volume)).toFixed(2)):null;assert.equal(s.teaserCubicPrice,expected);}});
test('default Beijing and no silent term',()=>{const c=create();assert.equal(c.state().city,'北京');assert.equal(c.state().requirement.term_months,null);assert.equal(c.state().locationAuthorized,false);});
test('capacity precision and edges',()=>{const c=create();for(const x of [.5,3.5,199.99,200])assert(c.validCapacity(x));for(const x of [0,.49,200.01,.576,NaN,Infinity])assert(!c.validCapacity(x));assert.throws(()=>c.setRequirement(.576,null,false),/INVALID_CAPACITY/);});
test('lease term is explicit, including 2 months',()=>{const c=create();c.setRequirement(3.5,2,true);assert.equal(c.state().requirement.term_months,2);assert.throws(()=>c.setRequirement(3.5,null,true),/SELECT_TERM/);assert.throws(()=>c.setRequirement(3.5,2.5,true),/INVALID_TERM/);});
test('all scenarios are selectable and deterministic',()=>{for(const scene of F.scenarios){const a=create(),b=create();a.setScenario(scene.id);b.setScenario(scene.id);assert.deepEqual(a.state(),b.state());}assert.throws(()=>create().setScenario('bogus'),/UNKNOWN_SCENARIO/);});
test('closed/sold units and undersized selections blocked',()=>{const c=create();c.setScenario('normal');assert.throws(()=>c.select(['SIM_BJ05_U02']),/UNAVAILABLE/);assert.throws(()=>c.select(['SIM_BJ01_U02']),/UNAVAILABLE/);assert.throws(()=>c.select(['SIM_BJ01_U01']),/UNAVAILABLE/);});
test('cross-store and duplicate units blocked',()=>{const c=create();c.setScenario('normal');assert.throws(()=>c.select(['SIM_BJ01_U03','SIM_BJ02_U03']),/UNAVAILABLE/);assert.throws(()=>c.select(['SIM_BJ01_U03','SIM_BJ01_U03']),/UNAVAILABLE/);});
test('no match and empty city are genuine data outcomes',()=>{const c=create();c.setScenario('noMatch');assert.equal(c.matchingUnits().length,0);assert(F.stores.every(s=>c.combinations(s.id).length===0));c.setScenario('emptyCity');assert.equal(c.matchingUnits().length,0);});
test('alternatives exclude unavailable current store and sort by distance',()=>{const c=create();c.setScenario('soldout');const list=c.alternatives('SIM_BJ01');assert(list.length);assert(list.every(u=>u.store_id!=='SIM_BJ01'&&u.volume>=3.5&&c.available(u)));const d=list.map(u=>F.stores.find(s=>s.id===u.store_id).distance);assert.deepEqual(d,[...d].sort((a,b)=>a-b));});
test('nearby no-match expands past 3km using available data',()=>{const c=create();c.setScenario('noNear');const list=c.alternatives();assert(list.length);assert(list.every(u=>F.stores.find(s=>s.id===u.store_id).distance>3));});
test('authorization denial/failure and missing request cannot grant',()=>{const c=create();assert.throws(()=>c.resolvePhone('success'),/NO_PHONE_REQUEST/);for(const outcome of ['denied','failed']){c.requestPhone();c.resolvePhone(outcome);assert.equal(c.authorized(),false);}assert.equal(c.state().requirement.term_months,null);});
test('dates are validated without defaults',()=>{const c=ready();c.setDate('2026-11-02');assert.throws(()=>c.setDate('2026-02-30'),/SELECT_DATE/);assert.throws(()=>c.setDate('2020-01-01'),/SELECT_DATE/);const x=create();x.setScenario('normal');authorized(x);x.select(['SIM_BJ01_U03']);assert.throws(()=>x.quote(),/SELECT_DATE/);});
test('known single order exact amount',()=>{const c=ready();const q=c.quote();assert.equal(q.rent_total,1680);assert.equal(q.deposit,280);assert.equal(q.management_fee,50);assert.equal(q.payable,2010);assert.equal(q.term_months,6);assert.equal(q.capacity_m3,3.5);});
test('combo is one order, deposits sum, management charged once',()=>{const c=create();c.setScenario('combo');authorized(c);const combo=c.combinations('SIM_BJ02').find(x=>x.ids.includes('SIM_BJ02_U03')&&x.ids.includes('SIM_BJ02_U04'));assert(combo);c.select(combo.ids);c.setDate(F.defaultStart);const q=c.quote();assert.equal(q.rent_total,4490);assert.equal(q.deposit,748);assert.equal(q.management_fee,50);assert.equal(q.payable,5288);assert.equal(c.submit().unit_ids.length,2);assert.equal(c.state().orders.length,1);});
test('inventory changes block submission, preserve demand and offer recovery',()=>{const c=ready('inventoryChanged');c.quote();const before=c.state().requirement;assert.throws(()=>c.submit(),/INVENTORY_CHANGED/);assert.deepEqual(c.state().requirement,before);assert.equal(c.state().quote,null);const alternative=c.alternatives('SIM_BJ01')[0];c.select([alternative.id]);c.quote();assert.equal(c.submit().store_id,alternative.store_id);});
test('price changes require explicit new quote',()=>{const c=ready('priceChanged');const old=c.quote();assert.throws(()=>c.submit(),/PRICE_CHANGED/);assert.equal(c.state().orders.length,0);assert.throws(()=>c.submit(),/QUOTE_STALE/);const fresh=c.quote();assert(fresh.payable>old.payable);assert.equal(c.submit().payable,fresh.payable);});
test('requirement/city/date changes invalidate quote',()=>{const c=ready();c.quote();c.setDate('2026-11-02');assert.equal(c.state().quote,null);c.quote();c.setRequirement(4,6,true);assert.equal(c.state().quote,null);assert.equal(c.state().selected.length,0);c.setCity('上海');assert.equal(c.state().requirement.capacity_m3,4);assert.equal(c.state().selected.length,0);});
test('expired quote blocked',()=>{let now=0;const c=ready('normal',()=>now);c.quote();now=300001;assert.throws(()=>c.submit(),/QUOTE_STALE/);});
test('expired or revoked authorization blocks',()=>{let now=0;const c=ready('normal',()=>now);c.quote();now=1800001;assert.throws(()=>c.submit(),/PHONE_REQUIRED/);assert.equal(c.state().quote,null);authorized(c);c.revokePhone();assert.equal(c.authorized(),false);});
test('tampered quote amount rejected',()=>{const c=ready();c.quote();const s=c.state();s.quote.payable=1;const restored=create({state:s});assert.throws(()=>restored.submit(),/QUOTE_STALE/);});
test('duplicate submit returns one order and reserves units',()=>{const c=ready();c.quote();const a=c.submit(),b=c.submit();assert.equal(a.id,b.id);assert.equal(c.state().orders.length,1);assert.equal(c.available(F.units.find(u=>u.id===a.unit_ids[0])),false);});
test('payment failure releases units; success occupies them',()=>{const c=ready();c.quote();const a=c.submit();c.pay(a.id,'failed');assert(c.available(F.units.find(u=>u.id===a.unit_ids[0])));c.quote();const b=c.submit();c.pay(b.id,'success');assert.equal(c.state().stock[b.unit_ids[0]],'occupied');assert.equal(c.pay(b.id,'failed').status,'paid_simulated');assert.throws(()=>c.pay(b.id,'invalid'),/INVALID_PAYMENT_OUTCOME/);});
test('address-only lead creates no order/store/unit association',()=>{const c=create();c.setStore('SIM_BJ01');assert.throws(()=>c.saveLead(''),/ENTER_ADDRESS/);const l=c.saveLead('北京市演示小区A座');assert.equal(l.address,'北京市演示小区A座');assert.equal(l.store_id,undefined);assert.equal(l.unit_ids,undefined);assert.equal(c.state().orders.length,0);assert.equal(c.state().leads.length,1);});
test('state hydration remains fixture-isolated and fresh visits capped',()=>{const c=ready();assert.equal(c.consumePreview(),true);assert.equal(c.consumePreview(),false);const b=create({state:c.state()});assert.deepEqual(b.state(),c.state());assert.equal(b.consumePreview(),false);const wrong={...c.state(),fixtureVersion:'central-data'};assert.equal(create({state:wrong}).state().requirement.capacity_m3,null);});
console.log(JSON.stringify({groups:tests,fixtureVersion:F.version,stores:F.stores.length,units:F.units.length,scenarios:F.scenarios.length,result:'PASS'}));
